def shortest_path(graph, source, target):
    # Early return for unreachable source
    if source not in graph:
        raise ValueError(f"Source node {source} not in graph")
    # Early return for unreachable target
    if target not in graph:
        raise ValueError(f"Target node {target} not in graph")

    # Distance from source to all other nodes (using BFS)
    def bfs_distance(graph, source):
        queue = deque([(source, 0)])
        visited = {source}
        distance = {source: 0}

        while queue:
            node, dist = queue.popleft()
            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    distance[neighbor] = dist + weight
                    queue.append((neighbor, dist + weight))
        return distance

    # Find shortest path using BFS distance to target
    distance_target = bfs_distance(graph, target)
    if target not in distance_target:
        return float("inf"), None

    # Reconstruct the path using BFS
    def bfs_path(graph, source, target):
        queue = deque([(source, repeat(None))])
        visited = {source}

        while queue:
            node, path = queue.popleft()
            for neighbor, weight in graph[node]:
                if neighbor == target:
                    yield path + (neighbor,)
                elif neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + (node,)))

    # Find and return the shortest path
    for path in bfs_path(graph, source, target):
        if sum(distance_target[node] for node in path) < float("inf"):
            return (sum(distance_target[node] for node in path), path)
    return float("inf"), None

